// ===== GETTER =====
function gt(k,lang){return(T[lang]&&T[lang][k])||T.EN[k]||'';}

// ===== GLOBAL STATE =====
var curLang='EN';

// ===== BUILD PICKER =====
function buildPicker(){
var wrap=document.createElement('div');wrap.id='pgGlobalLangPicker';
wrap.innerHTML='<div id="pgGlobalLangBtn" title="Change language"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg><span id="pgGlobalFlag">\u{1F1FA}\u{1F1F8}</span><span id="pgGlobalCode">EN</span></div><div id="pgGlobalLangDD"></div>';
document.body.appendChild(wrap);
var dd=document.getElementById('pgGlobalLangDD');
LANGS.forEach(function(L){
var r=document.createElement('div');r.className='pgGlob-row'+(L.code==='EN'?' active':'');
r.setAttribute('data-lang',L.code);
r.innerHTML='<span class="gf">'+L.flag+'</span><span class="gc">'+L.code+'</span><span class="gn">'+L.name+'</span>';
r.onclick=function(){setLang(L.code,L.flag);};
dd.appendChild(r);
});
document.getElementById('pgGlobalLangBtn').onclick=function(e){e.stopPropagation();dd.classList.toggle('open');};
document.addEventListener('click',function(e){if(!wrap.contains(e.target))dd.classList.remove('open');});
}

// ===== SET LANGUAGE =====
function setLang(code,flag){
curLang=code;
var gf=document.getElementById('pgGlobalFlag'),gc=document.getElementById('pgGlobalCode');
if(gf)gf.textContent=flag;if(gc)gc.textContent=code;
document.querySelectorAll('.pgGlob-row').forEach(function(r){r.classList.toggle('active',r.getAttribute('data-lang')===code);});
var dd=document.getElementById('pgGlobalLangDD');if(dd)dd.classList.remove('open');
var cf=document.getElementById('pgChat-lang-flag');if(cf)cf.textContent=flag;
applyAll(code);
updateChat(code);
try{localStorage.setItem('pgLang',code);}catch(e){}
}

// ===== APPLY TO ALL SITE ELEMENTS =====
function applyAll(lang){
document.querySelectorAll('[data-i18n]').forEach(function(el){
var k=el.getAttribute('data-i18n'),v=gt(k,lang);
if(v){
var toggle=el.querySelector('.toggle');
var ck=el.querySelector('.ck,.check');
if(el.tagName==='A'&&el.getAttribute('href')){
el.textContent=v;
}else{
el.textContent=v;
}
if(toggle)el.appendChild(toggle);
if(ck){el.insertBefore(ck,el.firstChild);el.insertBefore(document.createTextNode(' '),ck.nextSibling);}
}
});
}

// ===== UPDATE CHAT WIDGET =====
function updateChat(lang){
var t1=document.querySelector('#pgChat-header-left div div:first-child');
var t2=document.querySelector('#pgChat-header-left div div:last-child');
if(t1)t1.textContent=gt('chatT',lang);
if(t2)t2.textContent=gt('chatSub',lang);
var inp=document.getElementById('pgChat-input');
if(inp)inp.placeholder=gt('chatPH',lang);
window._pgChatLang=lang;
// Re-render welcome message + suggestion buttons if chat is showing welcome state
if(typeof window.pgChat!=='undefined'&&typeof window.pgChat.renderWelcome==='function'){
// Only re-render if no user messages yet (welcome state)
var msgs=document.getElementById('pgChat-messages');
if(msgs){
var userMsgs=msgs.querySelectorAll('.pgChat-msg.user');
if(!userMsgs||userMsgs.length===0){
window.pgChat.renderWelcome();
}
}
}
}

// ===== TAG NAV (only elements without data-i18n in HTML) =====
function tagAll(){
var navA=document.querySelectorAll('nav.nav ul.nav-links li a');
var nk=['navSS','navFeat','navPrice1','navDemo','navPrice2','navFAQ','navConnect'];
navA.forEach(function(a,i){if(nk[i]&&!a.getAttribute('data-i18n'))a.setAttribute('data-i18n',nk[i]);});
var navCTA=document.querySelector('nav.nav .nav-cta a');
if(navCTA&&!navCTA.getAttribute('data-i18n'))navCTA.setAttribute('data-i18n','navCTA');
// All other elements are tagged directly in HTML with data-i18n attributes
}

// ===== CSS =====
var css=document.createElement('style');
css.textContent='#pgGlobalLangPicker{position:fixed;bottom:24px;left:24px;z-index:99998}'
+'#pgGlobalLangBtn{display:flex;align-items:center;gap:6px;padding:6px 12px;background:var(--bg-surface,#161b22);border:1px solid var(--border,rgba(255,255,255,0.08));border-radius:8px;cursor:pointer;color:var(--text-muted,rgba(255,255,255,0.6));font-family:inherit;font-size:0.78rem;font-weight:600;box-shadow:0 4px 20px rgba(0,0,0,0.4);transition:transform 0.15s,box-shadow 0.15s,border-color 0.15s;white-space:nowrap}'
+'#pgGlobalLangBtn:hover{transform:scale(1.05);box-shadow:0 6px 28px rgba(0,0,0,0.5);border-color:rgba(125,211,252,0.25)}'
+'#pgGlobalLangBtn svg{color:var(--text-muted,rgba(255,255,255,0.5))}'
+'#pgGlobalFlag{font-size:1rem}#pgGlobalCode{color:#7dd3fc;font-family:"Fira Code",monospace;font-weight:700}'
+'#pgGlobalLangDD{display:none;position:absolute;bottom:44px;left:0;width:260px;max-height:420px;overflow-y:auto;background:var(--bg-surface,#161b22);border:1px solid var(--border,rgba(255,255,255,0.08));border-radius:12px;padding:6px;box-shadow:0 12px 48px rgba(0,0,0,0.7);scrollbar-width:thin;scrollbar-color:rgba(125,211,252,0.15) transparent}'
+'#pgGlobalLangDD::-webkit-scrollbar{width:4px}#pgGlobalLangDD::-webkit-scrollbar-thumb{background:rgba(125,211,252,0.15);border-radius:2px}'
+'#pgGlobalLangDD.open{display:block}'
+'.pgGlob-row{display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:8px;cursor:pointer;font-size:0.82rem;color:#e8ecf4;transition:background 0.12s;border:1px solid transparent}'
+'.pgGlob-row:hover{background:rgba(125,211,252,0.08)}'
+'.pgGlob-row.active{background:rgba(124,58,237,0.15);border-color:rgba(124,58,237,0.3)}'
